package com.aistock.prediction.marketuse;

import com.aistock.common.marketlifecycle.*;
import com.aistock.prediction.portfolioanalysis.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static com.aistock.prediction.maas.MaasOperationGate.*;

/** Existing non-reclaimable portfolio lease UUID is the execution identity; no positions or tokens persisted. */
public final class PortfolioMarketUseOwner {
 private record Binding(MarketUseClient.Request request,MarketUseClient.Receipt receipt,boolean started,boolean acked){}
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final PortfolioRepository portfolios;private final MarketUseClient client;private final Clock clock;private final boolean enabled;private final TransactionTemplate tx;
 public PortfolioMarketUseOwner(JdbcTemplate jdbc,ObjectMapper json,PortfolioRepository portfolios,MarketUseClient client,Clock clock,boolean enabled){this.jdbc=jdbc;this.json=json;this.portfolios=portfolios;this.client=client;this.clock=clock;this.enabled=enabled;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);}
 public boolean enabled(){return enabled;}
 public MarketUseContext.Scope acquire(UUID owner,UUID request,UUID execution,List<String> stocks){
  if(!enabled)return MarketUseContext.empty();var b=prepare(owner,request,stocks,execution);client.requireReady();if(b.receipt()==null){MarketUseClient.Receipt receipt;if(b.started())receipt=client.find(b.request()).orElseThrow(MarketUseClient::unavailable);else{if(start(owner,request,stocks,execution))receipt=client.register(b.request());else receipt=client.find(b.request()).orElseThrow(MarketUseClient::unavailable);}attach(execution,receipt);b=read(execution);}return MarketUseContext.open(b.request(),b.receipt());
 }
 private Binding prepare(UUID owner,UUID request,List<String> stocks,UUID execution){return tx.execute(s->{var selector=portfolios.useInput(owner,request,execution,stocks,clock);var b=read(execution);if(b!=null){var who=jdbc.queryForMap("select owner_id,request_id from portfolio_market_use where execution_id=?",execution.toString());if(!owner.toString().equals(who.get("owner_id"))||!request.toString().equals(who.get("request_id"))||!b.request().selector().equals(selector))throw MarketUseClient.invalid();return b;}jdbc.update("insert into portfolio_market_use(execution_id,owner_id,request_id,market_request_id,selector_json,created_at,last_checked_at) values(?,?,?,?,?,?,?)",execution.toString(),owner.toString(),request.toString(),UUID.randomUUID().toString(),encode(selector),ts(clock.instant()),ts(clock.instant()));return read(execution);});}
 private boolean start(UUID owner,UUID request,List<String> stocks,UUID execution){return Boolean.TRUE.equals(tx.execute(s->{portfolios.useInput(owner,request,execution,stocks,clock);return jdbc.update("update portfolio_market_use set registration_started=true where execution_id=? and registration_started=false",execution.toString())==1;}));}
 private Binding read(UUID execution){var rows=jdbc.queryForList("select * from portfolio_market_use where execution_id=?",execution.toString());if(rows.isEmpty())return null;var row=rows.get(0);try{var selector=json.readValue(row.get("selector_json").toString(),MarketUseRecords.Selector.class);return new Binding(new MarketUseClient.Request(execution.toString(),"1",row.get("market_request_id").toString(),"PORTFOLIO_VALUATION",selector),row.get("receipt_json")==null?null:json.readValue(row.get("receipt_json").toString(),MarketUseClient.Receipt.class),Boolean.TRUE.equals(row.get("registration_started")),Boolean.TRUE.equals(row.get("completion_acked")));}catch(java.io.IOException e){throw MarketUseClient.invalid();}}
 private void attach(UUID execution,MarketUseClient.Receipt receipt){tx.executeWithoutResult(s->{jdbc.queryForMap("select * from portfolio_market_use where execution_id=? for update",execution.toString());var b=read(execution);if(b==null||!b.started()||receipt.versionIds().size()!=b.request().selector().instruments().size())throw MarketUseClient.invalid();if(b.receipt()!=null){if(!b.receipt().bundleId().equals(receipt.bundleId())||!b.receipt().versionIds().equals(receipt.versionIds()))throw MarketUseClient.invalid();return;}jdbc.update("update portfolio_market_use set bundle_id=?,receipt_json=? where execution_id=? and bundle_id is null",receipt.bundleId(),encode(receipt),execution.toString());});}
 public JsonNode proof(UUID execution,String generation){if(!"1".equals(generation))throw MarketUseClient.unavailable();return tx.execute(s->{var state=portfolios.executionTerminal(execution,clock);var b=read(execution);if(b==null||b.receipt()==null)throw MarketUseClient.unavailable();var n=((ObjectNode)state).deepCopy();n.put("owner","prediction").put("purpose","PORTFOLIO_VALUATION").put("ownerOperationId",execution.toString()).put("generation","1");n.set("versionIds",json.valueToTree(b.receipt().versionIds()));return n;});}
 public void notifyCompleted(UUID execution){if(!enabled)return;try{var b=read(execution);if(b==null||b.receipt()==null||b.acked())return;proof(execution,"1");mark(execution.toString());var r=client.complete(b.request(),b.receipt());if(r==null||!"RELEASED".equals(r.state())||!b.receipt().bundleId().equals(r.bundleId())||!b.receipt().versionIds().equals(r.versionIds()))throw MarketUseClient.invalid();jdbc.update("update portfolio_market_use set completion_acked=true where execution_id=? and bundle_id=?",execution.toString(),b.receipt().bundleId());}catch(RuntimeException ignored){/* Committed attempt and pending receipt remain. */}}
 public void recoverOne(UUID execution){if(!enabled)return;try{mark(execution.toString());var b=read(execution);if(b==null||b.acked()||!b.started())return;if(b.receipt()==null){var r=client.find(b.request());if(r.isEmpty())return;attach(execution,r.get());}notifyCompleted(execution);}catch(RuntimeException ignored){/* Never infer release or submit another registration. */}}
 public void recoverBatch(){if(!enabled)return;var ids=jdbc.queryForList("select execution_id from portfolio_market_use where registration_started=true and completion_acked=false order by last_checked_at,execution_id limit 25",String.class);for(var id:ids){mark(id);try{recoverOne(UUID.fromString(id));}catch(RuntimeException ignored){/* Even malformed keys rotate without releasing. */}}}
 private void mark(String id){jdbc.update("update portfolio_market_use set last_checked_at=greatest(?,timestampadd(microsecond,1000,last_checked_at)) where execution_id=?",ts(clock.instant()),id);}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(java.io.IOException e){throw MarketUseClient.invalid();}}
}
